from fastapi import APIRouter, FastAPI, FastAPIError
import pytest

def test_include_router_itself():
    router = APIRouter()
    try:
        router.include_router(router)
    except FastAPIError as e:
        print(f"Caught expected error: {e}")
        return
    except Exception as e:
        print(f"Caught unexpected exception: {type(e).__name__}: {e}")
        raise e

    print("Failed: No error raised when including router into itself")
    raise AssertionError("No error raised when including router into itself")

if __name__ == "__main__":
    try:
        test_include_router_itself()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        exit(1)

from fastapi import FastAPI, APIRouter
from fastapi.exceptions import FastAPIError

def test_fastapi_include_itself():
    app = FastAPI()
    try:
        app.include_router(app)
    except FastAPIError as e:
        print(f"Caught expected error: {e}")
        return
    except Exception as e:
        print(f"Caught unexpected exception: {type(e).__name__}: {e}")
        raise e

    print("Failed: No error raised when including FastAPI app into itself")
    raise AssertionError("No error raised when including FastAPI app into itself")

if __name__ == "__main__":
    try:
        test_fastapi_include_itself()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        exit(1)

